package jp.sakai.fanza.draft;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{EditText source,out;public void onCreate(Bundle b){super.onCreate(b);LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(32,28,32,28);x.addView(t("③ X投稿文作成",24));source=e("作品情報");source.setMinLines(6);x.addView(source);Button r=btn("クリップボード読込・投稿文作成");r.setOnClickListener(v->make());x.addView(r);out=e("投稿文");out.setMinLines(8);x.addView(out);Button c=btn("投稿文をコピー");c.setOnClickListener(v->copy());x.addView(c);setContentView(x);getWindow().setStatusBarColor(Color.rgb(216,27,96));}
TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setPadding(0,10,0,10);return v;}EditText e(String h){EditText v=new EditText(this);v.setHint(h);v.setTextSize(16);return v;}Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);return b;}String f(String s,String k){for(String l:s.split("\n"))if(l.startsWith(k))return l.substring(k.length()).trim();return "";}void make(){ClipboardManager m=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(!m.hasPrimaryClip()){toast("作品情報がありません");return;}String s=m.getPrimaryClip().getItemAt(0).coerceToText(this).toString();source.setText(s);String title=f(s,"TITLE:"),act=f(s,"ACTRESS:"),url=f(s,"AFFILIATE:");String who=act.isEmpty()?"注目作品":act+"さんの注目作品";out.setText("【気になる新作】\n"+who+"『"+title+"』をチェック。\n\n内容・サンプルはこちら👇\n"+url+"\n\n#PR #FANZA");}void copy(){String s=out.getText().toString().trim();if(s.isEmpty()){toast("先に投稿文を作成してください");return;}((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("X投稿文",s));toast("投稿文をコピーしました。次は⑤です");}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}}
